fn boolean(value:i64)->Result<bool,String>{match value{0=>Ok(false),1=>Ok(true),_=>Err("Workflow flag must be zero or one".into())}}
fn enum32(value:i64)->Result<u32,String>{u32::try_from(value).map_err(|_|"Workflow enum must be an unsigned ordinal".into())}
